<script setup lang="ts">
import {onMounted,ref,reactive} from 'vue';
import {api,download,type Actor,type Row} from './api';
import DataTable from './DataTable.vue';
const props=defineProps<{me:Actor;employee?:boolean}>();
const admin=props.me.roles.split(',').includes('ADMIN')&&!props.employee;
const states:Row={WAITING:'待到访',ARRIVED:'已到访',LEFT:'已离开',CANCELLED:'已取消',EXPIRED:'已过期'};
const rows=ref<Row[]>([]),hosts=ref<Row[]>([]),detail=ref<Row|null>(null),summary=ref<Row>({}),editing=ref(false),temporary=ref(false),busy=ref(false),error=ref(''),message=ref(''),code=ref(''),offset=ref(0);
const filters=reactive<Row>({from:'',to:'',status:'',hostId:'',keyword:'',mine:props.employee?'true':''});
const fields=[['name','访客姓名',100],['phone','手机号',20],['company','单位',200],['purpose','来访事由',1000],['people','人数',3],['companions','随行人姓名（可空）',1000],['startAt','预计开始时间',30],['endAt','预计结束时间',30],['plate','车牌号（可空）',30],['note','备注（可空）',2000]] as const;
const form=reactive<Row>({});
function params(){return new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([,v])=>v!=='')))}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){rows.value=await api('/visitors?'+params()+'&offset='+offset.value);summary.value=await api('/visitors/summary')}
function edit(temp=false){temporary.value=temp;Object.keys(form).forEach(k=>delete form[k]);form.people=1;editing.value=true;detail.value=null}
async function save(){detail.value=await api('/visitors'+(temporary.value?'/temporary':''),'POST',{...form,people:Number(form.people),hostId:temporary.value?Number(form.hostId):undefined});editing.value=false;await load();message.value=temporary.value?'临时来访已登记并通知接待人':'预约成功，请向访客提供访客码'}
async function act(id:number,action:string){detail.value=await api('/visitors/'+id+'/'+action,'POST');await load();message.value='操作已完成'}
function today(){const date=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());filters.from=date;filters.to=date;offset.value=0}
onMounted(()=>run(async()=>{await load();if(admin)hosts.value=await api('/visitors/hosts')}));
</script>
<template>
<section class="card"><h2>访客管理</h2><p>简单来访登记 · 北京时间 · 今日预约 {{summary.todayReservations??0}} · 当前在场 {{summary.present??0}}</p>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<div class="actions"><button :disabled="busy" @click="edit()">预约访客</button><button :disabled="busy" @click="run(async()=>{filters.mine='true';offset=0;await load()})">我的访客</button><button :disabled="busy" @click="run(load)">刷新访客</button><button v-if="admin" :disabled="busy" @click="run(async()=>{today();await load()})">今日访客</button><button v-if="admin" :disabled="busy" @click="edit(true)">临时登记</button><button v-if="admin" :disabled="busy" @click="run(()=>download('/visitors/export?'+params(),'访客台账.csv'))">导出访客 CSV</button></div>
<form v-if="admin" class="filters" @submit.prevent="run(async()=>{detail=await api('/visitors/check-in','POST',{code});await load();message='签到成功，已通知接待人'})"><label>六位访客码<input v-model="code" required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" /></label><button :disabled="busy">凭码签到</button></form>
<form class="filters" @submit.prevent="run(async()=>{offset=0;await load()})"><label>开始日期<input v-model="filters.from" type="date" /></label><label>结束日期<input v-model="filters.to" type="date" /></label><label>访客状态<select v-model="filters.status"><option value="">全部状态</option><option v-for="(label,key) in states" :key="key" :value="key">{{label}}</option></select></label><label v-if="!employee">可见范围<select v-model="filters.mine"><option value="">全部可见访客</option><option value="true">我的访客</option></select></label><label v-if="!employee">接待人ID<input v-model="filters.hostId" type="number" min="1" /></label><label>访客关键字<input v-model="filters.keyword" maxlength="100" placeholder="姓名、单位、访客码、接待人" /></label><button :disabled="busy">查询访客</button></form>
<DataTable :rows="rows.map(r=>({...r,state:states[r.status]}))" :columns="[{key:'name',label:'访客姓名'},{key:'phone',label:'手机号'},{key:'company',label:'单位'},{key:'host_name',label:'接待人'},{key:'people',label:'人数'},{key:'start_at',label:'预计开始'},{key:'code',label:'访客码'},{key:'state',label:'状态'}]"><template #actions="{row}"><button :disabled="busy" @click="run(async()=>{detail=await api('/visitors/'+row.id)})">查看访客</button><button v-if="admin&&row.status==='WAITING'" :disabled="busy" @click="run(()=>act(row.id,'check-in'))">签到</button><button v-if="admin&&row.status==='ARRIVED'" :disabled="busy" @click="run(()=>act(row.id,'check-out'))">签离</button></template></DataTable>
<div class="pagination"><button :disabled="busy||!offset" @click="run(async()=>{offset-=200;await load()})">上一页</button><span>第 {{offset/200+1}} 页</span><button :disabled="busy||rows.length<200" @click="run(async()=>{offset+=200;await load()})">下一页</button></div></section>
<div v-if="editing||detail" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="访客登记与详情"><div class="modal-header"><h2>{{editing?(temporary?'临时来访登记':'预约访客'):'访客详情'}}</h2><button @click="editing=false;detail=null">关闭访客窗口</button></div><p v-if="error" class="error" role="alert">{{error}}</p>
<form v-if="editing" @submit.prevent="run(save)"><label v-if="temporary">在职接待人<select v-model="form.hostId" required><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}}（{{h.employee_no}}）</option></select></label><label v-for="[key,label,max] in fields" :key="key">{{label}}<input v-model="form[key]" :type="key.endsWith('At')?'datetime-local':key==='people'?'number':'text'" :min="key==='people'?1:undefined" :max="key==='people'?100:undefined" :maxlength="max" :required="!['companions','plate','note'].includes(key)" :pattern="key==='phone'?'[0-9]{7,20}':undefined" /></label><p>时间按北京时间填写，无需审批。访客信息仅用于来访登记。</p><button :disabled="busy">{{temporary?'登记并签到':'确认预约'}}</button></form>
<template v-else-if="detail"><h3>{{detail.name}} · {{states[detail.status]}}</h3><p>访客码：<strong>{{detail.code}}</strong></p><p>接待人：{{detail.host_name}} · {{detail.temporary?'临时登记':'预约'}}</p><p>手机号：{{detail.phone}} · 单位：{{detail.company}}</p><p>来访事由：{{detail.purpose}} · 人数：{{detail.people}} · 随行人：{{detail.companions||'无'}}</p><p>预计：{{detail.start_at}} 至 {{detail.end_at}}</p><p>签到：{{detail.checked_in_at||'未签到'}} · 签离：{{detail.checked_out_at||'未签离'}}</p><p>车牌号：{{detail.plate||'无'}} · 备注：{{detail.note||'无'}}</p><button v-if="detail.isOwner&&detail.status==='WAITING'" :disabled="busy" @click="run(()=>act(detail!.id,'cancel'))">取消预约</button><button v-if="admin&&detail.status==='WAITING'" :disabled="busy" @click="run(()=>act(detail!.id,'check-in'))">签到</button><button v-if="admin&&detail.status==='ARRIVED'" :disabled="busy" @click="run(()=>act(detail!.id,'check-out'))">签离</button></template>
</section></div>
</template>
